import os
import re
import shutil

from functools import partial
from zipfile import ZipFile

from ute_common_downloader.shell import Shell
from ute_common_downloader.connection import Connection
from ute_common_downloader.exception import ExecutionError


class AdaptationVersions(object):

    def get_from_enb(self, enb_ip='192.168.255.1', partition='active', output_dir='.'):
        """Downloads the AdaptationVersions file from given partition of eNB to output_dir and returns its path, or None if it is unavailable."""
        partition_path = '/ffs/run/' if partition == 'active' else '/ffs/stb'
        conn = Connection()
        conn.host = enb_ip
        conn.username = 'toor4nsn'
        conn.password = 'oZPS0POrRieRtu'
        shell = Shell(conn)
        try:
            output = shell.execute_command('ls {}/AdaptationVersions*.xml'.format(partition_path))
            filepath = output.splitlines()[-1]
            adaptation_versions_name = filepath.split('/')[-1]
            shell.copy_file(filepath, os.path.join(output_dir, adaptation_versions_name))
            return os.path.join(output_dir, adaptation_versions_name)
        except ExecutionError:
            return None

    def get_from_enb_sw_zip(self, sw_zip_path, output_dir='.'):
        """Extracts the AdaptationVersions file from given eNB SW package to output_dir. Both puttibatti- and BTSSM-based packages are supported.
        Returns the path where the file was extracted or None if it is unavailable."""
        sw_zip = ZipFile(sw_zip_path)
        matching_files = [path for path in sw_zip.namelist() if re.match('.*AdaptationVersions.*.xml$', path)]
        if matching_files:
            return self._extract_to_dir(sw_zip, matching_files[0], output_dir)
        else:
            return None

    def _extract_to_dir(self, zip, path_in_zip, output_dir):
        dest_file_name = os.path.join(output_dir, os.path.basename(path_in_zip))
        with zip.open(path_in_zip) as source_file, open(dest_file_name, 'w') as dest_file:
            shutil.copyfileobj(source_file, dest_file)
        return dest_file_name

    def find_in_directory(self, directory):
        """Returns the path to the AdaptationVersions file in given directory, or None if it could not be found."""
        matching_files = [file_name for file_name in os.listdir(directory) if re.match('AdaptationVersions.*xml', file_name)]
        return os.path.join(directory, matching_files[0]) if matching_files else None
